command:
set -euo pipefail
git log --no-merges --format='@@@%H%x09%ad%x09%s' --date=short --name-only d33c62eebc48de5e8a65c50e057addf25f125c6b..51e7faddad943ab7727e407d008e474ec076566d |
awk '
function flush() {
  if (!seen) return;
  commits++;
  if (prod) prod_count++;
  if (tests) test_count++;
  if (docs) docs_count++;
  if (tasks) tasks_count++;
  if (infra) infra_count++;
  if (evidence) evidence_count++;
  if (prod && tests) prod_tests++;
  if (prod && docs) prod_docs++;
  if (prod && docs && tests) prod_docs_tests++;
  if (prod && !tests) prod_without_tests++;
  if (!prod && !tests && docs && !infra) docs_only++;
  if (!prod && !tests && tasks && !docs && !infra) tasks_only++;
  if (!prod && !tests && !docs && !tasks && infra) infra_only++;
}
function reset() {prod=tests=docs=tasks=infra=evidence=0}
BEGIN {reset()}
$0 ~ /^@@@/ {flush(); seen=1; reset(); next}
NF == 0 {next}
$0 ~ /^(src|methods)\// {prod=1}
$0 ~ /^(tests|benchmarks)\// {tests=1}
$0 ~ /^docs\// || $0 ~ /README\.md$/ {docs=1}
$0 ~ /^tasks\// {tasks=1}
$0 ~ /^(tools|cmake|\.github)\// || $0 ~ /^(CMakeLists\.txt|CMakePresets\.json|vcpkg\.json|vcpkg-configuration\.json)$/ {infra=1}
$0 ~ /^tasks\/evidence\// {evidence=1}
END {
  flush();
  printf "non_merge_commits\t%d\n", commits;
  printf "production_source_commits\t%d\n", prod_count;
  printf "test_or_benchmark_commits\t%d\n", test_count;
  printf "docs_commits\t%d\n", docs_count;
  printf "task_commits\t%d\n", tasks_count;
  printf "infra_tooling_commits\t%d\n", infra_count;
  printf "evidence_commits\t%d\n", evidence_count;
  printf "production_plus_tests\t%d\n", prod_tests;
  printf "production_plus_docs\t%d\n", prod_docs;
  printf "production_plus_docs_plus_tests\t%d\n", prod_docs_tests;
  printf "production_without_tests_in_same_commit\t%d\n", prod_without_tests;
  printf "docs_only\t%d\n", docs_only;
  printf "tasks_only\t%d\n", tasks_only;
  printf "infra_only\t%d\n", infra_only;
}'

